with lib;
{
  ex00 = isAttrs {};
  #ex01 = isX "a"; 
  #ex02 = isX (-3); 
  #ex03 = isX (x: x);
  #ex04 = isX (x:x);
  #ex05 = isX ("x");
  #ex06 = isX null; 
  #ex07 = isX (y: y+1);
  #ex08 = isX [({z}: z) (x: x)];
  #ex09 = isX {a=[];};
  #ex10 = isX -10; # oh, what is that?
}

solution:
with import <nixpkgs> {};
with lib;
{
  ex00 = isAttrs {};
  ex01 = isString "a"; 
  ex02 = isInt (-3); 
  ex03 = isFunction (x: x);
  ex04 = isString (x:x); # this is because of url parsing: foo = http://bar.com;
  ex05 = isString ("x");
  ex06 = isNull null; 
  ex07 = isFunction (y: y+1);
  ex08 = isList [({z}: z) (x: x)];
  ex09 = isAttrs {a=[];};
  ex10 = isInt (-10); # () were missing
}

